parameters.jsonBody:
={
  "model": "kling",
  "task_type": "video_generation",
  "input": {
    "prompt": "{{ $json.data.input.prompt }}",
    "negative_prompt": "blurry motion, distorted faces, unnatural lighting, over produced, bad quality",
    "cfg_scale": 0.5,
    "duration": 5,
    "mode": "std",
    "image_url": "{{ $json.data.output.image_url }}",
    "version": "1.6",
    "camera_control": {
      "type": "simple",
      "config": {
        "horizontal": 0,
        "vertical": 0,
        "pan": 0,
        "tilt": 0,
        "roll": 0,
        "zoom": 5
      }
    }
  },
  "config": {}
}
